select year(sale_date) sale_year, case when year(sale_date) < 2024 then 'before_2024' when year(sale_date) = 2024 then '2024' else 'after_2024' end sale_cohort, sum(units) total_units, round(avg(units), 2) avg_units from store_sales group by 1, 2 having round(avg(units), 2) < 22 order by sale_cohort
